    except ValueError:
        return None
    local_seconds = moment.toordinal() * 86400 + moment.hour * 3600 + moment.minute * 60 + moment.second
    seconds = local_seconds - moment.utcoffset() // timedelta(seconds=1)
    return seconds, Decimal(fractional or "0")


